  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.font = `600 ${Math.round(5 * k)}px "LGS Inter", "Helvetica Neue", Helvetica, Arial, sans-serif`;
  g.fillText('assPod', W / 2, 52 * k);
