  let index = 0;
  let first = 0;
  let hiSince = 0;          // when the highlight landed: the marquee clock
  let hiOverflow = false;   // set at draw time, read by animating()
  let hiTextW = 0;
  let hiBoxW = 0;
  let lastMarqueeX = 0;
  const stepTimes = new Float64Array(10);   // ring of recent scroll times, for acceleration
  let stepHead = 0;
