  g.fillStyle = 'rgba(255,255,255,0.35)';
  g.fillRect(2, 2, 20, 3);
  g.strokeStyle = C.batteryBorder;
  g.lineWidth = 1;
  roundRectPath(g, 0.5, 0.5, 23, 10, 1.5);
  g.stroke();
