  g.translate(x, y);
  g.fillStyle = gradient(g, 0, 0, 0, h, C.hi);
  g.fillRect(0, 0, w, h);
  g.fillStyle = C.hiTop;
  g.fillRect(0, 0, w, 1);
  g.fillStyle = C.hiBottom;
  g.fillRect(0, h - 1, w, 1);
  g.restore();
