  const cy = y + M.rowH / 2;
  const boxW = rowLabelWidth(g, w, item);

  g.save();
  g.textBaseline = 'alphabetic';
  g.textAlign = 'left'; // callers may leave the context right-aligned
  g.fillStyle = color;
  g.font = FONTS.row;
